import type { LookId } from "./look.ts";
import type { Move } from "./world.ts";

/** `lang` is the site's language as an HTML lang code, English (`en`) when not given. */
export type SiteChoices = { look: LookId; move?: Move; words: Partial<Record<ChapterKey, string>>; cv?: string; lang?: string };

